style.css:
/* Pink Starry — TikTok */

:root {
  --my-pink: #ff83b8;
  --my-baby-pink: #fff0f7;
  --my-white: #ffffff;
  --my-text: #e879ad;
}

/* fondo rosado */
html, body {
  background: #fff0f7 !important;
  color: var(--my-text) !important;
}

/* letras rosadas */
p, span, a, h1, h2, h3 {
  color: var(--my-text) !important;
}

/* botones sin bordes */
button {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  background-color: transparent !important;
}

/* corazón rosado sin círculo */
[data-e2e="like-icon"] svg {
  fill: #ff83b8 !important;
  stroke: none !important;
}

/* mensajes y tarjetas */
img, video {
  border-radius: 12px !important;
}

/* selección rosada */
::selection {
  background: #ffafd0 !important;
  color: white !important;
}

/* scrollbar */
::-webkit-scrollbar-thumb {
  background: #f5a5ca !important;
  border-radius: 20px !important;
}
